import { Injectable, inject } from '@angular/core';
import { NzMessageService } from 'ng-zorro-antd/message';

/** hrm message — feedback global nhẹ. Bọc NzMessageService.
 *  content do nơi gọi truyền vào (đã i18n ở tầng gọi) → service không giữ text cứng.
 *  duration (ms) tùy chọn; loading() trả messageId để remove() thủ công (loading → xong). */
@Injectable({ providedIn: 'root' })
export class HrmMessageService {
  private readonly nz = inject(NzMessageService);

  success(content: string, duration?: number): void { this.nz.success(content, this.opts(duration)); }
  info(content: string, duration?: number): void { this.nz.info(content, this.opts(duration)); }
  warning(content: string, duration?: number): void { this.nz.warning(content, this.opts(duration)); }
  error(content: string, duration?: number): void { this.nz.error(content, this.opts(duration)); }

  /** Thông báo đang xử lý. duration=0 → giữ tới khi remove(). Trả messageId để đóng thủ công. */
  loading(content: string, duration?: number): string {
    return this.nz.loading(content, this.opts(duration)).messageId;
  }

  /** Đóng 1 thông báo theo id (từ loading), hoặc đóng tất cả nếu bỏ trống. */
  remove(id?: string): void { this.nz.remove(id); }

  private opts(duration?: number) {
    return duration === undefined ? undefined : { nzDuration: duration };
  }
}
